import 'package:flutter/material.dart';
import '../../models/career.dart';
import '../../services/api_client.dart';
import '../../services/local_vault.dart';
class ProfileScreen extends StatefulWidget{const ProfileScreen({super.key,required this.api,required this.vault,required this.onActivity});final ApiClient api;final LocalVault vault;final VoidCallback onActivity;@override State<ProfileScreen> createState()=>_ProfileScreenState();}
class _ProfileScreenState extends State<ProfileScreen>{final loc=TextEditingController(),person=TextEditingController(),rel=TextEditingController(),hobby=TextEditingController(),free=TextEditingController();String status='就業中（転職を検討中）',gender='未回答・回答しない',priority='ワークライフバランス・心の平穏';@override void initState(){super.initState();_load();}Future<void>_load()async{try{final x=await widget.api.get('/profile');if(!mounted)return;_apply(ProfileData.fromJson(x));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('サーバーからプロフィールを取得できませんでした。再接続後にもう一度お試しください。')));}}void _apply(ProfileData p){loc.text=p.location;person.text=p.personality;rel.text=p.relationships;hobby.text=p.hobbies;free.text=p.freeText;setState((){status=p.status;gender=p.gender;priority=p.priority;});}Future<void>save()async{final p=ProfileData(freeText:free.text,status:status,gender:gender,location:loc.text,personality:person.text,relationships:rel.text,hobbies:hobby.text,priority:priority);try{await widget.api.put('/profile',p.toJson());await widget.vault.saveProfile(p);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('プロフィールを保存しました')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('プロフィールを保存できませんでした。サーバーの状態を確認してください。')));}} Widget f(String l,TextEditingController c)=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,onChanged:(_){widget.onActivity();setState((){});},decoration:InputDecoration(labelText:l)));@override void dispose(){for(final c in [loc,person,rel,hobby,free]){c.dispose();}super.dispose();}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('個人プロフィール・カルテ',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Card(child:Padding(padding:EdgeInsets.all(14),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.edit_note_outlined),SizedBox(width:10),Expanded(child:Text('プロフィールはいつでも変更できます。今の自分に合わせて、自由に更新してください。\nAIが見つけた傾向も、違うと思ったらいつでも修正・削除できます。',style:TextStyle(fontSize:13,height:1.5)))]))),const SizedBox(height:16),DropdownButtonFormField(value:status,items:const ['就業中（転職を検討中）','就業中（現職維持・改善希望）','求職中・離職中','学生（就職活動中・進路検討中）','フリーランス・個人事業主'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>status=v!)),const SizedBox(height:12),f('居住地域',loc),f('性格傾向',person),f('人間関係・職場環境',rel),f('趣味・関心',hobby),f('カルテメモ',free),DropdownButtonFormField(value:priority,items:const ['ワークライフバランス・心の平穏','給与・年収アップ','専門スキル習得・成長','人間関係・人間関係のストレス軽減','自由な働き方・フルリモート'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>priority=v!)),const SizedBox(height:16),FilledButton.icon(onPressed:save,icon:const Icon(Icons.save_outlined),label:const Text('保存'))]);}
